// maxSimpleBatchSiblings bounds the list of packages shown for one upload. An
// upload is what one click produced, so this is far past any real batch; it
// only stops a client that reuses a single identifier for everything from
// turning the run screen into an unbounded listing of its own history.
const maxSimpleBatchSiblings = 100

// listBatchSiblings returns the other runs of the same upload, oldest first.
// The batch identifier comes from the client, so a stranger's run that happens
// to carry the same one must not be listed: the caller was authorised for this
// run's actor, and that is exactly whose runs these are restricted to.
//
// A read that stops part way through is reported rather than returned as a
// short list: a screen that shows only the packages that succeeded, because the
// row naming the failed one never arrived, is worse than one that says it could
// not look.
func (s *Server) listBatchSiblings(ctx context.Context, batchID, runID, actorID string) ([]map[string]any, error) {
	items := []map[string]any{}
	if batchID == "" || actorID == "" {
		return items, nil
	}
	rows, err := s.store.Pool.Query(ctx, `SELECT run.id::text,run.original_filename,run.status,
		run.batch_last,run.created_at
		FROM simple_runs run
		WHERE run.batch_id=$1 AND run.actor_id=$2 AND run.id<>$3
		ORDER BY run.created_at,run.id LIMIT $4`, batchID, actorID, runID, maxSimpleBatchSiblings)
	if err != nil {
		return items, err
	}
	defer rows.Close()
	for rows.Next() {
		var id, filename, status string
		var last bool
		var created time.Time
		if err := rows.Scan(&id, &filename, &status, &last, &created); err != nil {
			return []map[string]any{}, err
		}
		items = append(items, map[string]any{
			"id": id, "filename": filename, "status": status,
			"batchLast": last, "createdAt": created,
		})
	}
	if err := rows.Err(); err != nil {
		return []map[string]any{}, err
	}
	return items, nil
}

// streamSimpleRunLogs mirrors streamReleaseLogs: poll every second, keepalive
// every 15s, resume from Last-Event-ID, and stop once the run is terminal.
func (s *Server) streamSimpleRunLogs(w http.ResponseWriter, r *http.Request) {
	flusher, ok := w.(http.Flusher)
	if !ok {
		writeError(w, http.StatusInternalServerError, "stream_unsupported", "streaming is not supported")
		return
	}
	runID := r.PathValue("id")
	if _, err := s.authorizeRun(r, runID); err != nil {
		writeError(w, http.StatusNotFound, "not_found", "실행 기록을 찾을 수 없습니다")
		return
	}
	var status string
	err := s.store.Pool.QueryRow(r.Context(), `SELECT status FROM simple_runs WHERE id=$1`, runID).Scan(&status)
	if errors.Is(err, pgx.ErrNoRows) {
		writeError(w, http.StatusNotFound, "not_found", "실행 기록을 찾을 수 없습니다")
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "database_error", "could not load simple run")
		return
	}
	p, _ := principalFrom(r)
	if !s.acquireLogStream(p.UserID) {
		writeError(w, http.StatusTooManyRequests, "stream_limit", "too many concurrent log streams")
		return
	}
	defer s.releaseLogStream(p.UserID)

	lastID, _ := strconv.ParseInt(r.Header.Get("Last-Event-ID"), 10, 64)
	if queryID, _ := strconv.ParseInt(r.URL.Query().Get("after"), 10, 64); queryID > lastID {
		lastID = queryID
	}
	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Cache-Control", "no-cache, no-transform")
	w.Header().Set("X-Accel-Buffering", "no")
	w.WriteHeader(http.StatusOK)

	pollTicker := time.NewTicker(time.Second)
	keepaliveTicker := time.NewTicker(15 * time.Second)
	maxDuration := time.NewTimer(30 * time.Minute)
	defer pollTicker.Stop()
	defer keepaliveTicker.Stop()
	defer maxDuration.Stop()
	for {
		rows, err := s.store.Pool.Query(r.Context(),
			`SELECT id,stream,payload,created_at FROM simple_run_logs WHERE run_id=$1 AND id>$2 ORDER BY id LIMIT 500`, runID, lastID)
		if err != nil {
			return
		}
		sent := false
		for rows.Next() {
			var id int64
			var stream string
			var payload []byte
			var created time.Time
			if rows.Scan(&id, &stream, &payload, &created) != nil {
				break
			}
			encoded, _ := json.Marshal(map[string]any{"id": id, "stream": stream, "message": string(payload), "createdAt": created})
			fmt.Fprintf(w, "id: %d\nevent: log\ndata: %s\n\n", id, encoded)
			lastID = id
			sent = true
		}
		rows.Close()
		if sent {
			flusher.Flush()
		}
		_ = s.store.Pool.QueryRow(r.Context(), `SELECT status FROM simple_runs WHERE id=$1`, runID).Scan(&status)
		if !sent && (status == "SUCCESS" || status == "FAILED" || status == "TIMEOUT") {
			encoded, _ := json.Marshal(map[string]any{"status": status})
			fmt.Fprintf(w, "event: end\ndata: %s\n\n", encoded)
			flusher.Flush()
			return
		}
		select {
		case <-r.Context().Done():
			return
		case <-maxDuration.C:
			fmt.Fprint(w, "event: end\ndata: {\"reason\":\"max_duration\"}\n\n")
			flusher.Flush()
			return
		case <-keepaliveTicker.C:
			fmt.Fprint(w, ": keepalive\n\n")
			flusher.Flush()
		case <-pollTicker.C:
		}
	}
}

// errSimpleTargetAmbiguous means the caller omitted the target while more than
// one active target exists, so the server must not guess.
var errSimpleTargetAmbiguous = errors.New("simple target is ambiguous")

// resolveSimpleTarget loads the requested target, or the only active one when
// the caller did not name it. This is what lets the deploy screen accept a
// plain drag-and-drop with no selection step.
func (s *Server) resolveSimpleTarget(r *http.Request, targetID string) (simpleTarget, error) {
	if strings.TrimSpace(targetID) != "" {
		return scanSimpleTarget(s.store.Pool.QueryRow(r.Context(),
			`SELECT `+simpleTargetColumns+` FROM simple_targets WHERE id=$1 AND revoked_at IS NULL AND active`, targetID))
	}
	var count int
	if err := s.store.Pool.QueryRow(r.Context(),
		`SELECT count(*) FROM simple_targets WHERE revoked_at IS NULL AND active`).Scan(&count); err != nil {
		return simpleTarget{}, err
	}
	switch {
	case count == 0:
		return simpleTarget{}, pgx.ErrNoRows
	case count > 1:
		return simpleTarget{}, errSimpleTargetAmbiguous
	}
	return scanSimpleTarget(s.store.Pool.QueryRow(r.Context(),
		`SELECT `+simpleTargetColumns+` FROM simple_targets WHERE revoked_at IS NULL AND active LIMIT 1`))
}

// maxSimpleLogPage bounds one page of log lines so a very long run cannot force
// an unbounded response.
const maxSimpleLogPage = 2000

// listSimpleRunLogs returns stored output for a run. Unlike the SSE stream this
// works for a run that already finished, which is what makes the history usable
// after the fact. `format=text` returns the whole log as a plain download.
func (s *Server) listSimpleRunLogs(w http.ResponseWriter, r *http.Request) {
	runID := r.PathValue("id")
	if _, err := s.authorizeRun(r, runID); err != nil {
		writeError(w, http.StatusNotFound, "not_found", "실행 기록을 찾을 수 없습니다")
		return
	}
	if strings.EqualFold(r.URL.Query().Get("format"), "text") {
		s.downloadSimpleRunLog(w, r, runID)
		return
	}
	after, _ := strconv.ParseInt(r.URL.Query().Get("after"), 10, 64)
	limit := maxSimpleLogPage
	if requested, err := strconv.Atoi(r.URL.Query().Get("limit")); err == nil && requested > 0 && requested < limit {
		limit = requested
	}
	rows, err := s.store.Pool.Query(r.Context(),
		`SELECT id,stream,payload,created_at FROM simple_run_logs
		 WHERE run_id=$1 AND id>$2 ORDER BY id LIMIT $3`, runID, after, limit)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "database_error", "could not read run logs")
		return
	}
	defer rows.Close()
	items := []map[string]any{}
	// A page with no rows leaves the cursor where the caller had it. Reporting 0
	// instead would tell a caller that asked past the end of the log to start
	// over from the first line.
	lastID := after
	for rows.Next() {
		var id int64
		var stream string
		var payload []byte
		var created time.Time
		if rows.Scan(&id, &stream, &payload, &created) != nil {
			writeError(w, http.StatusInternalServerError, "database_error", "could not read run logs")
			return
		}
		items = append(items, map[string]any{"id": id, "stream": stream, "message": string(payload), "createdAt": created})
		lastID = id
	}
	// The caller polls with `after` until hasMore is false, then switches to the
	// stream if the run is still going.
	writeJSON(w, http.StatusOK, map[string]any{
		"items":   items,
		"lastId":  lastID,
package server

import (
	"errors"
	"strings"
	"testing"
)

// The command's output and the server's progress lines must not compete for the
// same bytes. A deployment script that prints an image load or a build log can
// reach the cap on its own, and if that also silenced the server's lines the
// stored log would end mid-output with no "exit=" line and no record of whether
// replication and the application deployment ran.
func TestLogBudgetKeepsAReserveForServerLines(t *testing.T) {
	budget := newLogBudget()
	allowed, store, exhausted := budget.take("stdout", maxSimpleRunLogBytes)
	if allowed != maxSimpleRunLogBytes || !store || !exhausted {
		t.Fatalf("the command must be able to use its whole budget, got %d store=%v exhausted=%v", allowed, store, exhausted)
	}
	if allowed, store, _ := budget.take("stderr", 16); allowed != 0 || store {
		t.Fatalf("command output past the cap must be dropped, got %d store=%v", allowed, store)
	}
	if allowed, store, _ := budget.take(streamSystem, 64); allowed != 64 || !store {
		t.Fatalf("a server line must still be stored after the command filled the cap, got %d store=%v", allowed, store)
	}
}

// The notice that later output is dropped is written once, on the payload that
// uses up the last of the command budget, so a long run does not repeat it on
// every line it discards afterwards.
func TestLogBudgetReportsExhaustionOnce(t *testing.T) {
	budget := logBudget{command: 10, system: 10}
	allowed, store, exhausted := budget.take("stdout", 4)
	if allowed != 4 || !store || exhausted {
		t.Fatalf("a payload within the budget must not report exhaustion, got %d %v %v", allowed, store, exhausted)
	}
	// The payload that crosses the cap is stored up to the cap and reports it.
	allowed, store, exhausted = budget.take("stdout", 9)
	if allowed != 6 || !store || !exhausted {
		t.Fatalf("the crossing payload must be truncated and report exhaustion, got %d %v %v", allowed, store, exhausted)
	}
	if allowed, store, exhausted = budget.take("stdout", 3); allowed != 0 || store || exhausted {
		t.Fatalf("later output must be dropped silently, got %d %v %v", allowed, store, exhausted)
	}
}

// The reserve is a bound too: a stage that logged pathologically much cannot
// grow the run log without limit, and filling it never claims the command cap
// was reached.
func TestLogBudgetBoundsTheReserveWithoutReportingExhaustion(t *testing.T) {
	budget := logBudget{command: 10, system: 5}
	allowed, store, exhausted := budget.take(streamSystem, 12)
	if allowed != 5 || !store || exhausted {
		t.Fatalf("a server line must be truncated to the reserve, got %d %v %v", allowed, store, exhausted)
	}
	if allowed, store, _ := budget.take(streamSystem, 1); allowed != 0 || store {
		t.Fatalf("the reserve must not be exceeded, got %d %v", allowed, store)
	}
	if allowed, store, _ := budget.take("stdout", 10); allowed != 10 || !store {
		t.Fatal("a full reserve must not consume the command budget")
	}
}

// A blank line is output: deployment scripts use them to separate the sections
// an operator reads the log by, so one has to survive as a row of its own
// rather than be closed up against the line before it.
func TestLogBudgetStoresBlankLines(t *testing.T) {
	budget := logBudget{command: 10, system: 4}
	allowed, store, exhausted := budget.take("stdout", 0)
	if allowed != 0 || !store || exhausted {
		t.Fatalf("a blank line must be stored, got %d %v %v", allowed, store, exhausted)
	}
	if budget.command != 9 {
		t.Fatalf("a blank line must be charged, command = %d", budget.command)
	}
}

// Charging blank lines is what bounds them: a command that prints nothing but
// newlines runs into the same cap as one that prints text, instead of adding
// rows for as long as it runs.
func TestLogBudgetBoundsBlankLines(t *testing.T) {
	budget := logBudget{command: 2, system: 4}
	for range 2 {
		if _, store, _ := budget.take("stdout", 0); !store {
			t.Fatal("a blank line within the budget must be stored")
		}
	}
	if _, store, _ := budget.take("stdout", 0); store {
		t.Fatal("blank lines past the cap must be dropped like any other output")
	}
}

// Nothing is stored once the budget is gone, blank line or not, and reaching
// that point is reported only once.
func TestLogBudgetDropsEverythingOnceExhausted(t *testing.T) {
	budget := logBudget{command: 0, system: 4}
	if allowed, store, exhausted := budget.take("stdout", 0); allowed != 0 || store || exhausted {
		t.Fatalf("an exhausted budget must store nothing, got %d %v %v", allowed, store, exhausted)
	}
	if budget.system != 4 {
		t.Fatalf("a dropped command line must not charge the reserve, system = %d", budget.system)
	}
}

// The byte where the budget runs out can fall inside a multi-byte character. The
// stored line then ends before that character rather than with a fragment of
// it: a fragment reads as U+FFFD everywhere the log is shown, and the cap is a
// bound on bytes, not a promise to store exactly that many.
func TestTrimToRuneBoundaryEndsOnAWholeCharacter(t *testing.T) {
	cases := []struct {
		allowed int
		want    string
	}{
		{0, ""},
		{3, "가"},
		{4, "가"},
		{5, "가"},
		{6, "가나"},
		{9, "가나다"},
	}
	for _, c := range cases {
		got := trimToRuneBoundary([]byte("가나다"), c.allowed)
		if string(got) != c.want {
			t.Fatalf("trim %q to %d bytes = %q, want %q", "가나다", c.allowed, got, c.want)
		}
	}
}

// ASCII has no continuation bytes, so a cut in ASCII stays exactly at the
// budget: the accounting a reader sees for such a line does not change.
func TestTrimToRuneBoundaryKeepsAnASCIICutExact(t *testing.T) {
	if got := trimToRuneBoundary([]byte("abcdefg"), 3); string(got) != "abc" {
		t.Fatalf("an ASCII cut must stay at the budget, got %q", got)
	}
	if got := trimToRuneBoundary([]byte("abc"), 5); string(got) != "abc" {
		t.Fatalf("a budget past the end must keep the line whole, got %q", got)
	}
}

// Command output is not guaranteed to be UTF-8. A run of continuation bytes
// that never reaches a rune start must not be walked back to the start of the
// line; a character is at most four bytes, so at most three are ever dropped.
func TestTrimToRuneBoundaryNeverWalksBackPastOneCharacter(t *testing.T) {
	garbage := []byte{'a', 'b', 0x80, 0x80, 0x80, 0x80, 0x80, 0x80}
	got := trimToRuneBoundary(garbage, 7)
	if len(got) != 4 {
		t.Fatalf("invalid bytes must be cut at most three bytes early, got %d bytes %v", len(got), got)
	}
	// 0xFF is not a continuation byte, so a cut in front of it does not move.
	if got := trimToRuneBoundary([]byte{'a', 'b', 0xFF, 'c'}, 2); len(got) != 2 {
		t.Fatalf("a cut before a stray byte must not walk back, got %v", got)
	}
}

// fakeLogRows stands in for pgx.Rows so the download can be rendered - and made
// to fail part way through - without a database.
type fakeLogRows struct {
	lines   [][2]string
	index   int
	scanAt  int
	scanErr error
	err     error
}

func (r *fakeLogRows) Next() bool {
	r.index++
	return r.index <= len(r.lines)
}

func (r *fakeLogRows) Scan(dest ...any) error {
	if r.scanErr != nil && r.index == r.scanAt {
		return r.scanErr
	}
	line := r.lines[r.index-1]
	*(dest[0].(*string)) = line[0]
	*(dest[1].(*[]byte)) = []byte(line[1])
	return nil
}

func (r *fakeLogRows) Err() error { return r.err }

// The download is the plain text of the run: command output as it was written,
// stderr marked so the reader can tell the two apart.
func TestSimpleRunLogDownloadRendersEveryStream(t *testing.T) {
	var out strings.Builder
	writeSimpleRunLog(&out, &fakeLogRows{lines: [][2]string{
		{"stdout", "이미지를 불러옵니다"},
		{"stderr", "경고"},
		{streamSystem, "exit=0"},
	}})
	want := "이미지를 불러옵니다\n[stderr] 경고\nexit=0\n"
	if out.String() != want {
		t.Fatalf("unexpected download body %q", out.String())
	}
	if strings.Contains(out.String(), simpleRunLogTruncatedNotice) {
		t.Fatal("a log that was read to the end must not be marked as truncated")
	}
}

// A row that cannot be read stops the download, but 200 and the headers are
// already sent, so the only way to tell the operator is a line in the file. A
// silent return would save a log that ends mid-run and looks complete.
func TestSimpleRunLogDownloadMarksARowThatCouldNotBeRead(t *testing.T) {
	var out strings.Builder
	writeSimpleRunLog(&out, &fakeLogRows{
		lines:   [][2]string{{"stdout", "첫 줄"}, {"stdout", "둘째 줄"}},
		scanAt:  2,
		scanErr: errors.New("connection reset"),
	})
	if !strings.HasPrefix(out.String(), "첫 줄\n") {
		t.Fatalf("the lines read before the failure must be kept, got %q", out.String())
	}
	if !strings.Contains(out.String(), simpleRunLogTruncatedNotice+"connection reset") {
		t.Fatalf("the download must say it is truncated, got %q", out.String())
	}
}

// The result set can also end early without any row failing; only Err tells
// that apart from a log that simply ended.
func TestSimpleRunLogDownloadMarksAResultSetThatEndedEarly(t *testing.T) {
	var out strings.Builder
	writeSimpleRunLog(&out, &fakeLogRows{
		lines: [][2]string{{"stdout", "첫 줄"}},
		err:   errors.New("unexpected EOF"),
	})
	if !strings.Contains(out.String(), simpleRunLogTruncatedNotice+"unexpected EOF") {
		t.Fatalf("the download must say it is truncated, got %q", out.String())
	}
}

// The saved file names the package and how the run ended, because an operator
// working through a failed upload downloads several logs and could not tell
// them apart by run id alone.
func TestRunLogDownloadNameCarriesThePackageAndOutcome(t *testing.T) {
	name := runLogDownloadName("payments-api-1.4.2.tar.gz", "FAILED", "0f8b2a11-4c3d-4a1e-9b77-2f1d5c8e6a90", false)
	if name != "releasedock-payments-api-1.4.2.tar.gz-FAILED-0f8b2a11-4c3d-4a1e-9b77-2f1d5c8e6a90.log" {
		t.Fatalf("unexpected download name %q", name)
	}
}

// The name goes into a response header, so nothing the uploader chose may end
// up as a quote, a newline or a path of its own.
func TestRunLogDownloadNameNeverEscapesTheHeader(t *testing.T) {
	disposition := runLogDisposition("\"; rm -rf /\r\n../../etc/passwd", "SUCCESS", "0f8b2a11")
	if strings.ContainsAny(disposition, "\r\n") {
		t.Fatalf("the header must not carry a line break: %q", disposition)
	}
	if strings.Count(disposition, `"`) != 2 || strings.Contains(disposition, "/") {
		t.Fatalf("the file name must not carry a quote or a path separator: %q", disposition)
	}
	// An empty run id would leave a name that ends in a dash, so it falls back.
	if name := runLogDownloadName("", "", "", false); name != "releasedock-run.log" {
		t.Fatalf("unexpected fallback name %q", name)
	}
}

// Package names here are often Korean. Reducing them to ASCII would leave
// nothing to recognise, so the exact name travels in the extended form while
// the plain one stays conservative.
func TestRunLogDispositionKeepsAKoreanPackageNameInTheExtendedForm(t *testing.T) {
	disposition := runLogDisposition("결제-1.4.2.tar", "SUCCESS", "0f8b2a11")
	if !strings.Contains(disposition, `filename="releasedock-1.4.2.tar-SUCCESS-0f8b2a11.log"`) {
		t.Fatalf("unexpected plain name in %q", disposition)
	}
	encoded := encodeExtendedHeaderValue("releasedock-결제-1.4.2.tar-SUCCESS-0f8b2a11.log")
	if !strings.HasSuffix(disposition, "filename*=UTF-8''"+encoded) {
		t.Fatalf("unexpected extended name in %q", disposition)
	}
	if strings.ContainsAny(encoded, "결제") {
		t.Fatalf("the extended form must be percent-encoded, got %q", encoded)
	}
}

// A package name long enough to stretch the header is cut, and the cut never
